  return `import { ModuleRegistry } from 'ag-grid-community'; 
${imports.join(" \n")} 

ModuleRegistry.registerModules([ ${moduleNames.map((m2) => convertToUserModuleName(m2, true)).join(", ")} ]); 

For more info see: ${baseDocLink}/modules/`;
